insert into public.dataset_licenses (dataset_id, license_code, tier, task_pack)
select id, 'KOJOH-TDS-LIC-0001', 'standard', $pack${"phases": [{"key": "python", "title": "Phase 1 — Python: Clean the Data", "tasks": [{"id": "P7", "text": "Resolve every Sales Person entry to one of 56 distinct people. Each person appears under roughly 8 spellings, and Emp Code (blank on ~5% of rows, typo'd on more) only partly helps. Document your method — this is graded on defensibility, not just the final count."}, {"id": "P1", "text": "Load the raw CSV/XLSX and profile it: row count, column count, null counts per column, and a written note on the five things that look most wrong before you touch anything."}, {"id": "P6", "text": "Normalise Family Size (`4` / `4 members` / `Four`), Loan Tenure (`60` / `60 months` / `5 years` → months), Interest Rate (`8.72` / `8.72%` / `0.0872`), and Safety Rating (`5 Star` → 5)."}, {"id": "P2", "text": "Remove duplicate deal entries (~190 of them). State your de-duplication rule and how many genuine deals remain."}, {"id": "P5", "text": "Collapse Status into Closed / Open / Lost, standardise Fuel, Transmission and Colour text, and normalise Accessories Interest to a real boolean."}, {"id": "P3", "text": "Write a parser for the six currency text formats found across the nine money columns (plain, comma, `Rs` + Indian comma, lakh notation, space-padded, trailing-decimal) and apply it everywhere. Watch for rows using a different format in every money column."}, {"id": "P4", "text": "Write a parser for the five date formats across all four date columns, including Excel serial numbers (days since 1899-12-30). Derive a clean sales-month column from Booking Date, since the ERP's own Month field is ~40% blank."}]}, {"key": "sql", "title": "Phase 2 — SQL: Answer the Business Questions", "tasks": [{"id": "S5", "text": "Using a window function, find the single best month by total margin per branch (i.e., branch's own best month, not the group's)."}, {"id": "S6", "text": "Write a query comparing MY2025 vs MY2026 bookings in November+December 2025 only: average discount, average margin per car, and average days between booking and scheduled delivery, grouped by model_year."}, {"id": "S10", "text": "Cross-tabulate Payment Mode against Finance Bank: for financed deals only, count of deals and average down-payment percentage per bank."}, {"id": "S7", "text": "Find every Closed deal where final_price < floor_price (the below-floor leak). Group the result by branch and by month, ordered by count descending."}, {"id": "S8", "text": "Write a query ranking Variant Tier (Base/Mid/Top) by count of Closed deals and by average margin per car, in the same result set."}, {"id": "S11", "text": "Write a query showing, for each model, the average family_size of buyers and the model's seating capacity side by side, ordered by average family size."}, {"id": "S9", "text": "For every salesperson, find their single most-sold colour and what share of their total Closed deals it represents (use a window function to avoid a correlated subquery)."}, {"id": "S4", "text": "Compute average margin per deal (total margin ÷ closed deals) per salesperson. Return the top 10, alongside their volume rank from S1, in one query."}, {"id": "S3", "text": "Compute total negotiation margin (SUM(final_price - floor_price)) per salesperson on Closed deals, and rank them. Compare this rank against S1's rank for the same people — return the ones that moved by more than 20 places."}, {"id": "S12", "text": "Using a CTE, compute: of all customers who showed Accessories Interest, what share actually has a non-zero Accessories Value, and separately what share of *those* buyers also has a non-zero Post Delivery Accessory Value. This is a 3-stage funnel in one query."}, {"id": "S2", "text": "For each salesperson, compute conversion rate: Closed / (Closed+Open+Lost). Return anyone above 75% conversion, ordered by conversion descending."}, {"id": "S1", "text": "Rank the 56 salespeople by number of Closed deals. Return name, branch, deals closed and their rank."}]}, {"key": "dash1", "title": "Phase 3a — Dashboard Page 1: Deal Lookup", "tasks": [{"id": "D5", "text": "Make the deal-lookup results table itself filterable/sortable by any visible column, so someone can browse instead of only searching by exact Deal ID."}, {"id": "D1", "text": "Build a search box that takes a Deal ID and returns everything about that one deal on a single screen: salesperson + branch, car (model/variant/tier/fuel/colour/model year), the full price chain (ex-showroom → floor → quoted → discount → final), payment/finance detail, and the delivery timeline (enquiry → booking → scheduled → actual, with the gap called out)."}, {"id": "D3", "text": "Add a date-range filter on Booking Date and a separate date-range filter on (Scheduled or Actual) Delivery Date, and make sure both can be applied together."}, {"id": "D4", "text": "Add filters for Branch, Salesperson, Model, Status and Payment Mode that combine with the date filters (AND logic) rather than replacing them."}, {"id": "D2", "text": "On the same lookup screen, show customer context: family size, customer type, accessories taken, the face-to-face feedback reason, and any remarks."}]}, {"key": "dash2", "title": "Phase 3b — Dashboard Page 2: Analytics", "tasks": [{"id": "D14", "text": "Add a branch comparison panel: volume, margin, conversion and below-floor rate, all four metrics per branch in one view."}, {"id": "D6", "text": "Build a salesperson leaderboard panel showing volume, total margin and average margin per deal side by side, so 'best' is never reduced to one number the viewer can't question."}, {"id": "D15", "text": "Make every panel on Page 2 respect a global date-range filter (Booking Date), so the whole analytics page can be viewed for any period, not just the full year."}, {"id": "D13", "text": "Add a monthly trend panel showing volume and total margin together, so a viewer can see months where they move in opposite directions (like Oct/Mar in this dataset)."}, {"id": "D9", "text": "Add a discount panel: total and average discount given, trended by month, split by Scheme Applied."}, {"id": "D8", "text": "Add a panel on Safety Rating: what share of Closed deals were on 5-star vs 4-star rated models, and what share of *feedback reasons* actually cite the safety rating — these are two different numbers, show both."}, {"id": "D7", "text": "Add an average sale price panel, sliceable by Model, Branch and Variant Tier."}, {"id": "D11", "text": "Add an accessories panel: share of customers who showed interest vs who actually bought accessories vs who came back post-delivery, and the total revenue (and implied profit, at a margin % you define and state) each stage represents."}, {"id": "D10", "text": "Add a panel showing what share of billed/closed deals used each Scheme Applied value, ranked."}, {"id": "D12", "text": "Add a finance panel: Payment Mode split, and for financed deals, a breakdown of Finance Bank usage — both as a table and as a chart."}]}, {"key": "documentation", "title": "Phase 4 — Documentation", "tasks": [{"id": "DOC1", "text": "Write a short project write-up (any format — Word, PDF, Notion, a README, doesn't matter) with three sections: (1) **Process Flow** — how you actually went from the raw export to your cleaned data to your SQL answers to your dashboard, including the decisions you made (especially how you resolved salesperson identity); (2) **Key Discoveries** — your top 3–5 findings, stated as a decision-maker would want to hear them, not as code output; (3) **Future Growth Recommendations** — at least 3 concrete, data-backed recommendations for what Sanchay Motors should actually do next. This document is the deliverable a hiring manager or client would actually read — treat it that way."}]}, {"key": "stretch", "title": "Stretch ideas (optional)", "tasks": [{"id": "X-S4", "text": "Estimate what the December clearance actually cost the group in margin versus what it earned in volume and cleared inventory."}, {"id": "X-S1", "text": "Build a single composite salesperson scorecard combining volume, margin, conversion and below-floor discipline into one number. Defend your weights."}, {"id": "X-S2", "text": "Model the enquiry-to-booking gap: do faster-closing deals earn better or worse margins?"}]}]}$pack$::jsonb
from public.datasets where slug = 'tata-delhi-sales-fy2526'
on conflict (license_code) do nothing;

